insert into exame_preparo (nome_norm, jejum_horas, instrucoes) values
('ANTIBIOGRAMA [CULTURA DE URINA]',0,'["Jejum não obrigatório", "Comparecer ao laboratório sem urinar ou com intervalo de 2 horas.", "O ideal é que as amostras sejam colhidas antes da antibioticoterapia, ou alguns dias após o término do tratamento. Quando o paciente está em vigência de antibioticoterapia, este fato deve ser registrado pela recepção."]'::jsonb),
('ANTIBIOGRAMA [CULTURA DE SEC.VAGINAL]',0,'["Não é necessário jejum.", "A coleta ou entrega do material segue a orientação da recepção.", "Traga o pedido médico."]'::jsonb),
('ANTIBIOGRAMA [CULTURA DE SEC.URETRAL]',0,'["Jejum não obrigatório", "Comparecer ao laboratório sem urinar ou com intervalo de 2 horas.", "O ideal é que as amostras sejam colhidas antes da antibioticoterapia, ou alguns dias após o término do tratamento. Quando o paciente está em vigência de antibioticoterapia, este fato deve ser registrado pela recepção."]'::jsonb),
('ANTIBIOGRAMA [CULTURA DE FEZES]',0,'["Jejum não obrigatório", "O ideal é que as amostras sejam colhidas antes da antibioticoterapia, ou alguns dias após o término do tratamento. Quando o paciente está em vigência de antibioticoterapia, este fato deve ser registrado pela recepção.", "O Paciente deve, em meio de transporte com conservante fornecido pelo Laboratório, colher as primeiras fezes do dia e trazê-las ao Laboratório.\n    O ideal é que as amostras sejam colhidas antes da antibioticoterapia, ou alguns dias após o término do tratamento. Quando o paciente está em vigência de antibioticoterapia, este fato deve ser registrado pela Recepção.\nPara pacientes de urgência as amostras poderão ser colhidas a qualquer momento."]'::jsonb),
('CULTURA PARA FUNGOS [2. MATERIAL]',0,'["Jejum não obrigatório", "Comparecer ao laboratório sem ter usado qualquer tipo de creme  ou pomada (medicamento tópico) na região de interesse e/ou antifúngico via oral, durante 10 dias que antecedem a realização do exame. Para exames das unhas, comparecer sem esmalte. Lembrando que a higienização do local de interesse não interfere no exame."]'::jsonb),
('PESQUISA DE BACILO ALCOOL-ACIDO RESISTENTE [2]',0,'["O ideal é que as amostras sejam colhidas antes da antibioticoterapia, ou alguns dias após o término do tratamento. Quando o paciente está em vigência de antibioticoterapia, este fato deve ser registrado pela recepção.", "É possível realizar exame de bacterioscopia de Ziehl Neelsen em qualquer material clínico, com a finalidade de investigar presença de bacilos-álcool-ácido-resistentes. Lembrando que para cada material clínico, as orientações pré-analíticas, bem como, procedimentos de coleta, são específicas para cada tipo de exame, portanto, consultar exame específico ou seguir orientações solicitadas pelo médico."]'::jsonb),
